import (
	"encoding/json"
	"errors"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
)

// FromJSON creates a Theme from JSON data.
// The JSON should contain color definitions and other theme properties.
//
// Since: 2.2
func FromJSON(data []byte) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(string(data)))
}

// FromJSONReader creates a Theme from a JSON reader.
// The JSON should contain color definitions and other theme properties.
//
// Since: 2.2
func FromJSONReader(reader io.Reader) (fyne.Theme, error) {
	var themeData map[string]interface{}
	decoder := json.NewDecoder(reader)

	if err := decoder.Decode(&themeData); err != nil {
		return nil, err
	}

	// For now, return a basic theme implementation
	// A full implementation would parse the JSON and create a custom theme
	return &jsonTheme{data: themeData}, nil
}

// parseHexColor converts a hex color string (e.g., "#FF0000" or "FF0000") to a color.Color.
func parseHexColor(hex string) (color.Color, error) {
	hex = strings.TrimPrefix(hex, "#")

	if len(hex) != 6 && len(hex) != 8 {
		return nil, errors.New("invalid hex color format")
	}

	// Parse RGB components
	r, err := strconv.ParseUint(hex[0:2], 16, 8)
	if err != nil {
		return nil, err
	}
	g, err := strconv.ParseUint(hex[2:4], 16, 8)
	if err != nil {
		return nil, err
	}
	b, err := strconv.ParseUint(hex[4:6], 16, 8)
	if err != nil {
		return nil, err
	}

	// Parse alpha component if present
	a := uint64(255)
	if len(hex) == 8 {
		a, err = strconv.ParseUint(hex[6:8], 16, 8)
		if err != nil {
			return nil, err
		}
	}

	return color.NRGBA{R: uint8(r), G: uint8(g), B: uint8(b), A: uint8(a)}, nil
}

// jsonTheme is a basic implementation of a theme loaded from JSON
type jsonTheme struct {
	data map[string]interface{}
}

func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Try to find color in the data
	key := string(name)
	if variant == VariantDark {
		key = key + "_dark"
	}

	if hexStr, ok := t.data[key].(string); ok {
		if c, err := parseHexColor(hexStr); err == nil {
			return c
		}
	}

	// Fall back to default theme
	return DefaultTheme().Color(name, variant)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	return DefaultTheme().Font(style)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	return DefaultTheme().Icon(name)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	// Try to find size in the data
	if val, ok := t.data[string(name)].(float64); ok {
		return float32(val)
	}

	// Fall back to default theme
	return DefaultTheme().Size(name)
}
