// FromJSON creates a Theme from JSON data.
// The JSON should contain color definitions and other theme properties.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader creates a Theme from a JSON reader.
// The JSON should contain color definitions and other theme properties.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(reader io.Reader) (fyne.Theme, error) {
	var themeData jsonThemeData
	decoder := json.NewDecoder(reader)

	if err := decoder.Decode(&themeData); err != nil {
		return DefaultTheme(), err
	}

	return &jsonTheme{data: themeData}, nil
}

